fn mt19937(seed: u32) -> Vec<u32> {
    // MT19937 has a fixed state size of 624
    let mut state = vec![0u32; 624];
    state[0] = seed;
    for i in 0..623 {
        let prev = state[i];
        // Compute the recurrence with 32-bit wrap-around arithmetic
        let next = 1812433253u32
            .wrapping_mul(prev ^ (prev >> 30))
            .wrapping_add((i as u32) + 1);
        state[i + 1] = next;
    }
    state
}

